import{_ as a,o as t,c as i,a0 as n}from"./chunks/framework.LnjvHj4-.js";const c=JSON.parse('{"title":"Tutorial","description":"","frontmatter":{},"headers":[],"relativePath":"tutorial/index.md","filePath":"tutorial/index.md"}'),o={name:"tutorial/index.md"};function l(r,e,s,d,h,p){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="tutorial" tabindex="-1">Tutorial <a class="header-anchor" href="#tutorial" aria-label="Permalink to &quot;Tutorial&quot;">​</a></h1><p>For over a decade, it has been known that a subset of individuals with a genetic (Mendelian) disease have more than one such disease (<a href="https://pubmed.ncbi.nlm.nih.gov/27959697/" target="_blank" rel="noreferrer">Posey et al., 2017</a>). This situation has been referred to in the literature as blended phenotype, dual (or multiple) genetic diagnosis, Multilocus Genomic Variation, composite phenotype, co-occurrence of diseases, comorbidity, and others. For conciseness, we will use the acronym MGD (multiple genetic diagnosis).</p><p>Phenoblend is a desktop application designed to visualize the phenotypic profile observed in individuals with MGD. See the <a href="https://p2gx.github.io/phenoblendtk/" target="_blank" rel="noreferrer">Documentation</a> for information on installing and using Phenoblend.</p><h1 id="using-phenoblend" tabindex="-1">Using Phenoblend <a class="header-anchor" href="#using-phenoblend" aria-label="Permalink to &quot;Using Phenoblend&quot;">​</a></h1><p>Phenoblend is a desktop application that can be run on Mac, Windows, or several types of linux. Users need to load the required data and then can visualize the phenotypic profiles.</p><ul><li><a href="./../guides/installation.html">Installation</a></li><li><a href="./data.html">Loading HPO/HPOA data</a></li><li><a href="./input.html">Loading input data</a></li><li><a href="./visualizations.html">Visualizations</a></li><li><a href="./overlap.html">Understanding the overlap plot</a></li><li><a href="./upset.html">Understanding the upset plot</a></li><li><a href="./profile.html">Understanding the phenotype profile plot</a></li></ul>',6)])])}const f=a(o,[["render",l]]);export{c as __pageData,f as default};
